//! Discord's own icons: SVG paths taken from the web client's icon
//! components (24×24 view boxes), drawn with resvg at the exact pixel size
//! and tinted when painted. Textures live in the window's egui memory, so
//! they go with the window.

use egui::{Color32, Rect, TextureHandle};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Icon {
    Microphone,
    MicrophoneSlash,
    Headphones,
    HeadphonesSlash,
    Settings,
    PhoneCall,
    PhoneHangUp,
    Text,
    Voice,
    Announcements,
    Forum,
    Thread,
    Lock,
    Stage,
    Soundboard,
    Compass,
    Calendar,
    Video,
    VideoSlash,
    ScreenArrow,
    Activities,
    Friends,
    /// Message Requests (the bundle's EnvelopeIcon).
    Envelope,
    /// The Shop's row (ShopIcon).
    Shop,
    /// The Quests' row (QuestsIcon).
    Quests,
    /// Listening, in activity statuses (MusicIcon).
    Music,
    /// A muted channel's header bell (BellSlashIcon).
    BellSlash,
    /// Watching or streaming, in activity statuses (TvIcon).
    Tv,
    Pin,
    Search,
    Members,
    Plus,
    Discord,
    Chat,
    Check,
    Inbox,
    ChevronDown,
    UserPlus,
    CirclePlus,
    DoorExit,
    Gif,
    Sticker,
    Reaction,
    Reply,
    Pencil,
    Close,
    File,
    /// Discord's forward arrow (ArrowAngleRight).
    Forward,
    More,
    Trash,
    /// Switching accounts: the bundle's account menu uses a person in a
    /// circle for it.
    Switch,
    Refresh,
    /// The "ID" square of "Copy ID".
    Id,
    /// The title bar's help: a question mark in a circle.
    Help,
    /// A game controller: what a friend is playing.
    Controller,
    Spotify,
    /// A box with an arrow out of its corner: a link that leaves the app.
    Launch,
    /// An open eye, and one struck through: marking a file a spoiler.
    Eye,
    EyeSlash,
    /// The media viewer's magnifying glasses and its save button.
    ZoomIn,
    ZoomOut,
    Download,
    /// The expression picker's rail: frequently used, favourites, and the
    /// Unicode categories (people is the reaction face, activities the
    /// controller).
    Clock,
    Star,
    Nature,
    Food,
    Travel,
    Objects,
    Heart,
    Flag,
    /// The settings sidebar's marks, by page.
    Accessibility,
    Palette,
    Language,
    System,
    CreditCard,
    Gift,
    /// The composer's app launcher (the bundle's `AppsIcon`).
    Apps,
    /// "Show User Profile" in a DM's header (`UserCircleStatusIcon`).
    UserCircle,
    /// "Add Friends to DM" (`GroupPlusIcon`).
    GroupPlus,
    /// A friend, on a profile's banner (`UserCheckIcon`).
    UserCheck,
    /// "Add Note" beside a name in a DM's profile (`PaperPlusIcon`).
    PaperPlus,
    Nitro,
    Boost,
    Folder,
    Subscriptions,
    ActivityPrivacy,
    Link,
    Overlay,
    User,
    Clips,
    Privacy,
    Messaging,
    Bell,
    Developer,
    Info,
    Puzzle,
}

