/// Rasterizes an icon white on transparent, `px` pixels square.
fn rasterize(icon: Icon, px: u32) -> Option<egui::ColorImage> {
    let paths: String = icon
        .paths()
        .iter()
        .map(|d| format!(r#"<path fill="white" fill-rule="evenodd" d="{d}"/>"#))
        .collect();
    let svg = format!(r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">{paths}</svg>"#);
    let tree = resvg::usvg::Tree::from_str(&svg, &resvg::usvg::Options::default()).ok()?;
    let mut pixmap = resvg::tiny_skia::Pixmap::new(px, px)?;
    let scale = px as f32 / 24.0;
    resvg::render(&tree, resvg::tiny_skia::Transform::from_scale(scale, scale), &mut pixmap.as_mut());
    Some(egui::ColorImage::from_rgba_premultiplied(
        [px as usize, px as usize],
        pixmap.data(),
    ))
}

/// The icon's texture at `px` pixels square, rasterized once.
fn texture(ui: &egui::Ui, icon: Icon, px: u32) -> Option<TextureHandle> {
    let ctx = ui.ctx();
    let id = egui::Id::new(("cordfast-icon", icon, px));
    ctx.memory_mut(|m| m.data.get_temp::<TextureHandle>(id)).or_else(|| {
        let image = rasterize(icon, px)?;
        let texture = ctx.load_texture(format!("icon-{icon:?}-{px}"), image, egui::TextureOptions::LINEAR);
        ctx.memory_mut(|m| m.data.insert_temp(id, texture.clone()));
        Some(texture)
    })
}

/// Paints `icon` filling `rect`, in `color`.
pub fn paint(ui: &egui::Ui, rect: Rect, icon: Icon, color: Color32) {
    let px = (rect.width() * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    if let Some(texture) = texture(ui, icon, px) {
        egui::Image::from_texture((texture.id(), rect.size()))
            .tint(color)
            .paint_at(ui, rect);
    }
}

/// Discord's chevron pointing right (submenus): its down chevron, turned.
pub fn paint_chevron_right(ui: &egui::Ui, rect: Rect, color: Color32) {
    let px = (rect.width() * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    if let Some(texture) = texture(ui, Icon::ChevronDown, px) {
        egui::Image::from_texture((texture.id(), rect.size()))
            .tint(color)
            .rotate(-std::f32::consts::FRAC_PI_2, egui::Vec2::splat(0.5))
            .paint_at(ui, rect);
    }
}

/// `icon` turned about its upright axis, as a coin spins: `turn` is the
/// width left, from 1 (facing) through 0 (edge on) to -1 (its back).
pub fn paint_turned(ui: &egui::Ui, rect: Rect, icon: Icon, color: Color32, turn: f32) {
    let px = (rect.width() * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    if let Some(texture) = texture(ui, icon, px) {
        let shown = Rect::from_center_size(rect.center(), egui::vec2(rect.width() * turn.abs(), rect.height()));
        let uv = if turn < 0.0 { Rect::from_min_max(egui::pos2(1.0, 0.0), egui::pos2(0.0, 1.0)) } else { Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(1.0, 1.0)) };
        egui::Image::from_texture((texture.id(), shown.size())).uv(uv).tint(color).paint_at(ui, shown);
    }
}

/// `icon` turned by `angle` radians about its centre.
pub fn paint_rotated(ui: &egui::Ui, rect: Rect, icon: Icon, color: Color32, angle: f32) {
    let px = (rect.width() * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    if let Some(texture) = texture(ui, icon, px) {
        egui::Image::from_texture((texture.id(), rect.size()))
            .tint(color)
            .rotate(angle, egui::Vec2::splat(0.5))
            .paint_at(ui, rect);
    }
}

/// Discord's chevron pointing up (an open section): its down chevron, turned.
pub fn paint_chevron_up(ui: &egui::Ui, rect: Rect, color: Color32) {
    let px = (rect.width() * ui.ctx().pixels_per_point()).round().max(1.0) as u32;
    if let Some(texture) = texture(ui, Icon::ChevronDown, px) {
        egui::Image::from_texture((texture.id(), rect.size()))
            .tint(color)
            .rotate(std::f32::consts::PI, egui::Vec2::splat(0.5))
            .paint_at(ui, rect);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every icon's paths parse and draw something.
    #[test]
    fn icons_rasterize() {
        for icon in [Icon::Microphone, Icon::Text, Icon::Voice, Icon::Announcements, Icon::Forum, Icon::Thread, Icon::Lock, Icon::Stage, Icon::Friends, Icon::Pin, Icon::Search, Icon::Members, Icon::Plus, Icon::Discord, Icon::Chat, Icon::Check, Icon::Settings, Icon::PhoneCall, Icon::Inbox, Icon::ChevronDown, Icon::UserPlus, Icon::CirclePlus, Icon::DoorExit, Icon::Gif, Icon::Sticker, Icon::Reaction, Icon::Reply, Icon::Pencil, Icon::Close, Icon::File, Icon::Forward, Icon::More, Icon::Trash, Icon::Launch, Icon::Eye, Icon::EyeSlash, Icon::Switch, Icon::Id, Icon::Help, Icon::Controller, Icon::ZoomIn, Icon::ZoomOut, Icon::Download, Icon::Clock, Icon::Star, Icon::Nature, Icon::Food, Icon::Travel, Icon::Objects, Icon::Heart, Icon::Flag, Icon::Accessibility, Icon::Palette, Icon::Language, Icon::System, Icon::CreditCard, Icon::Gift, Icon::Nitro, Icon::Boost, Icon::Folder, Icon::Subscriptions, Icon::ActivityPrivacy, Icon::Link, Icon::Overlay, Icon::User, Icon::Clips, Icon::Privacy, Icon::Messaging, Icon::Bell, Icon::Developer, Icon::Info, Icon::Puzzle, Icon::Envelope, Icon::Shop, Icon::Quests, Icon::Music, Icon::Tv, Icon::BellSlash, Icon::Apps, Icon::UserCircle, Icon::GroupPlus, Icon::UserCheck, Icon::PaperPlus] {
            let image = rasterize(icon, 48).expect("rasterizes");
            let ink = image.pixels.iter().filter(|p| p.a() > 0).count();
            assert!(ink > 50, "{icon:?} drew {ink} pixels");
            if let Ok(dir) = std::env::var("CORDFAST_ICON_DUMP") {
                let rgba: Vec<u8> = image.pixels.iter().flat_map(|p| p.to_array()).collect();
                image::RgbaImage::from_raw(48, 48, rgba).unwrap().save(format!("{dir}/{icon:?}.png")).unwrap();
            }
        }
    }
}

/// Discord's status masks (from the web client, in a unit box): a circle
/// with a moon cut for idle, a bar for do-not-disturb, a hole for offline,
/// and a play arrow for streaming.
fn status_svg(status: &str) -> &'static str {
    match status {
        "idle" => r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><mask id="m"><circle fill="white" cx=".5" cy=".5" r=".5"/><circle fill="black" cx=".25" cy=".25" r=".375"/></mask><circle fill="white" cx=".5" cy=".5" r=".5" mask="url(#m)"/></svg>"#,
        "dnd" => r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><mask id="m"><circle fill="white" cx=".5" cy=".5" r=".5"/><rect fill="black" x=".125" y=".375" width=".75" height=".25" rx=".125" ry=".125"/></mask><circle fill="white" cx=".5" cy=".5" r=".5" mask="url(#m)"/></svg>"#,
        "streaming" => r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><mask id="m"><circle fill="white" cx=".5" cy=".5" r=".5"/><polygon fill="black" points="0.35,0.25 0.78301275,0.5 0.35,0.75"/></mask><circle fill="white" cx=".5" cy=".5" r=".5" mask="url(#m)"/></svg>"#,
        "online" => r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><circle fill="white" cx=".5" cy=".5" r=".5"/></svg>"#,
        _ => r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><mask id="m"><circle fill="white" cx=".5" cy=".5" r=".5"/><circle fill="black" cx=".5" cy=".5" r=".25"/></mask><circle fill="white" cx=".5" cy=".5" r=".5" mask="url(#m)"/></svg>"#,
    }
}

/// Discord's status colours.
pub fn status_color(status: &str) -> Color32 {
    match status {
        "online" => Color32::from_rgb(0x23, 0xa5, 0x5a),
        "idle" => Color32::from_rgb(0xf0, 0xb2, 0x32),
        "dnd" => Color32::from_rgb(0xf2, 0x3f, 0x43),
        "streaming" => Color32::from_rgb(0x59, 0x36, 0x95),
        _ => Color32::from_rgb(0x80, 0x84, 0x8e),
    }
}

/// Paints a status shape filling `rect`.
pub fn paint_status(ui: &egui::Ui, rect: Rect, status: &str) {
    let ctx = ui.ctx();
    let px = (rect.width() * ctx.pixels_per_point()).round().max(1.0) as u32;
    let key = match status {
        "online" | "idle" | "dnd" | "streaming" => status,
        _ => "offline",
    };
    let id = egui::Id::new(("cordfast-status", key, px));
    let texture = ctx.memory_mut(|m| m.data.get_temp::<TextureHandle>(id)).or_else(|| {
        let tree = resvg::usvg::Tree::from_str(status_svg(key), &resvg::usvg::Options::default()).ok()?;
        let mut pixmap = resvg::tiny_skia::Pixmap::new(px, px)?;
        resvg::render(&tree, resvg::tiny_skia::Transform::from_scale(px as f32, px as f32), &mut pixmap.as_mut());
        let image = egui::ColorImage::from_rgba_premultiplied([px as usize, px as usize], pixmap.data());
        let texture = ctx.load_texture(format!("status-{key}-{px}"), image, egui::TextureOptions::LINEAR);
        ctx.memory_mut(|m| m.data.insert_temp(id, texture.clone()));
        Some(texture)
    });
    if let Some(texture) = texture {
        egui::Image::from_texture((texture.id(), rect.size()))
            .tint(status_color(status))
            .paint_at(ui, rect);
    }
}

/// A square button showing one of Discord's icons, lit on hover.
pub fn button(ui: &mut egui::Ui, icon: Icon, size: f32, tooltip: &str) -> egui::Response {
    let p = crate::theme::p();
    let (rect, response) = ui.allocate_exact_size(egui::Vec2::splat(size), egui::Sense::click());
    if response.hovered() {
        ui.painter().rect_filled(rect, 4.0, p.hover);
    }
    let color = if response.hovered() { p.strong } else { p.muted };
    paint(ui, rect.shrink(size * 0.2), icon, color);
    response.on_hover_text(tooltip)
}

/// An avatar decoration drawn around an avatar, as Discord does (20% wider).
pub fn decoration(ui: &egui::Ui, images: &mut crate::images::Images, avatar: Rect, url: &str) {
    let ppp = ui.ctx().pixels_per_point();
    let frame = Rect::from_center_size(avatar.center(), avatar.size() * 1.2);
    if let Some((texture, _)) = images.get(url, (frame.width() * ppp) as u32) {
        egui::Image::from_texture((texture, frame.size())).paint_at(ui, frame);
    }
}
